{
  "name": "LLM Studio - LAPTOP",
  "description": "Single container LLM Studio for ACER Nitro V16 AI Laptop with RTX 5060 GPU",
  "version": "1.0.0",
  "environment": {
    "CUDA_VERSION": "13.2",
    "GPU_NAME": "NVIDIA GeForce RTX 5060",
    "VRAM_TOTAL": "8192",
    "VRAM_USABLE": "7340032",
    "LLAMA_N_CTX": "8192",
    "LLAMA_N_BATCH": "512",
    "LLAMA_NUM_PARALLEL": "2",
    "LLAMA_CUDA": "1"
  },
  "models": {
    "primary": "llama3:8b",
    "quantization": "q4_0",
    "compatible_gpus": ["RTX 3000 series", "RTX 4000 series", "RTX 5000 series", "A100", "A6000"]
  },
  "paths": {
    "models": "/home/sabeiro/Downloads/llm_model/models",
    "cache": "/home/sabeiro/Downloads/llm_cache/cache",
    "config": "/home/sabeiro/Downloads/llm_model/config.json",
    "history": "/home/sabeiro/Downloads/llm_model/history",
    "data": "/home/sabeiro/Downloads/llm_model/mdata",
    "uploads": "/home/sabeiro/Downloads/llm_model/uploads"
  },
  "volumes": {
    "models": {
      "source": "/home/sabeiro/Downloads/llm_model/models",
      "target": "/models",
      "read_only": false
    },
    "cache": {
      "source": "/home/sabeiro/Downloads/llm_cache/cache",
      "target": "/cache",
      "read_only": false
    },
    "data": {
      "source": "/home/sabeiro/Downloads/llm_model/mdata",
      "target": "/data",
      "read_only": false
    },
    "uploads": {
      "source": "/home/sabeiro/Downloads/llm_model/uploads",
      "target": "/uploads",
      "read_only": false
    },
    "config": {
      "source": "/home/sabeiro/Downloads/llm_model/config.json",
      "target": "/app/config.json",
      "read_only": true
    }
  },
  "deployment": {
    "compose_file": "docker-compose_laptop_single.yml",
    "image": "ghcr.io/huggingface-webui/webui-server:latest",
    "ports": ["7860:7860"],
    "gpu_devices": [
      "/dev/nvidia0:/dev/nvidia0",
      "/dev/nvidiactl:/dev/nvidiactl",
      "/dev/nvideact:/dev/nvideact",
      "/dev/nvmap:/dev/nvmap"
    ],
    "memory_limit": "6G",
    "cpu_limit": "4"
  },
  "monitoring": {
    "healthcheck": "http://localhost:7860",
    "logs_command": "docker-compose -f docker-compose_laptop_single.yml logs -f",
    "status_command": "docker-compose -f docker-compose_laptop_single.yml ps"
  }
}
